package com.primehr.rsp.screening.domain;
import com.primehr.rsp.domain.RspAuditedEntity; import jakarta.persistence.*; import org.hibernate.annotations.Nationalized; import java.time.Instant; import java.util.Objects;
@Entity @Table(name="rsp_screening_decision",uniqueConstraints=@UniqueConstraint(name="uk_rsp_screening_decision_case",columnNames={"agency_id","case_id"}))
public class ScreeningDecision extends RspAuditedEntity {
 @Column(name="case_id",nullable=false,length=36) private String caseId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ScreeningCase.Outcome outcome; @Column(name="reason_code_id",length=36) private String reasonCodeId; @Column(name="reason_code",length=80) private String reasonCode; @Nationalized @Column(name="internal_explanation",length=2000) private String internalExplanation; @Nationalized @Column(name="applicant_safe_reason",nullable=false,length=1000) private String applicantSafeReason; @Column(name="recommended_by",nullable=false,length=100) private String recommendedBy; @Column(name="validated_by",nullable=false,length=100) private String validatedBy; @Column(name="decided_at",nullable=false) private Instant decidedAt; @Column(name="administrator_override",nullable=false) private boolean administratorOverride; @Nationalized @Column(name="override_reason",length=2000) private String overrideReason;
 protected ScreeningDecision(){} public ScreeningDecision(String agency,String caseId,ScreeningCase.Outcome outcome,String reasonId,String reasonCode,String explanation,String safe,String recommender,String validator,Instant at,boolean override,String overrideReason){super(agency);this.caseId=requiredText(caseId,"caseId");this.outcome=Objects.requireNonNull(outcome);reasonCodeId=optionalText(reasonId);this.reasonCode=optionalText(reasonCode);internalExplanation=optionalText(explanation);applicantSafeReason=requiredText(safe,"applicantSafeReason");recommendedBy=requiredText(recommender,"recommendedBy");validatedBy=requiredText(validator,"validatedBy");decidedAt=Objects.requireNonNull(at);administratorOverride=override;this.overrideReason=optionalText(overrideReason);if(override&&this.overrideReason==null)throw new IllegalArgumentException("Override reason is required");}
 public String getCaseId(){return caseId;} public ScreeningCase.Outcome getOutcome(){return outcome;} public String getReasonCodeId(){return reasonCodeId;} public String getReasonCode(){return reasonCode;} public String getInternalExplanation(){return internalExplanation;} public String getApplicantSafeReason(){return applicantSafeReason;} public String getRecommendedBy(){return recommendedBy;} public String getValidatedBy(){return validatedBy;} public Instant getDecidedAt(){return decidedAt;} public boolean isAdministratorOverride(){return administratorOverride;} public String getOverrideReason(){return overrideReason;}
}
